-- Academy: rebuild Yachts Module 6 as "The Art of the Deal": 16 pages (8 with quick checks, 8 with answerable exercises
-- saved to the Broker Portfolio) + a 7-question final quiz. Same shape as the Module 1 migration.

do $mig$
declare
  v_module uuid;
  v_q uuid;
  v_page uuid;
  rec jsonb;
  n int := 0;
  i int;
  v_pages jsonb := $json$[{"heading": "The Art of the Deal", "body": "<p><b>How does a yacht actually get sold?</b></p><p>A yacht can look perfect on a screen. Beautiful photographs. Impressive specifications. An attractive asking price. A great location. Then a client says: <em>\"I'd like to see it.\"</em></p><p>At that moment, the yacht stops being a listing. It becomes an opportunity. And from here, the broker's job becomes much more demanding. A yacht transaction can involve:</p><p>&bull; buyer and seller<br/>&bull; buyer's broker and listing broker<br/>&bull; captain and crew<br/>&bull; surveyor, lawyers and yacht management<br/>&bull; insurers, financiers and registration authorities<br/>&bull; technical specialists, shipyards and many other professionals</p><p>The broker does not replace these specialists. The broker helps the client navigate the process, keeps communication moving, identifies issues, manages expectations and helps bring the right people together at the right time.</p><p>The process is not always linear. Deals can pause. Terms can change. Surveys can reveal problems. Financing can become complicated. Negotiations can break down. And sometimes a transaction simply does not happen. That is part of brokerage.</p><p>The professional skill is not making every deal happen. It is knowing how to move a serious transaction forward while protecting the client's interests, maintaining professionalism and keeping everyone aligned.</p>", "q": "What is the professional skill in a yacht transaction?", "opts": ["Making every deal happen at any cost", "Moving a serious transaction forward while protecting the client's interests and keeping everyone aligned", "Replacing the lawyers and surveyors", "Keeping the process as short as possible"], "correct": 1}, {"heading": "Chapter 1: From Client to Yacht", "body": "<p><b>The transaction starts before the yacht viewing</b></p><p>A common beginner mistake is to think the first major step is showing the yacht. It isn't. The first major step is understanding <b>why this particular yacht deserves the client's attention.</b> You have already learned how to build a client brief. Now you use it.</p><p>Imagine your client says: <em>\"I like the yacht. Let's go and see it.\"</em> A broker should still ask:</p><p>&bull; What specifically attracted them?<br/>&bull; Does the yacht actually fit the brief?<br/>&bull; What do we already know, and what remains uncertain?<br/>&bull; Who needs to be involved?<br/>&bull; Where is the yacht, and can it be viewed?<br/>&bull; Who controls access?<br/>&bull; What should the client know before the viewing?<br/>&bull; What should the broker observe during the viewing?</p><p>The viewing is an important event. But preparation determines how useful it becomes.</p><p><b>The transaction pathway</b></p><p>At a simplified level, a yacht sale may move through:</p><p><em>Client qualification → Yacht identification → Initial research → Viewing → Further questions and due diligence → Offer → Negotiation → Agreement → Deposit and contractual process → Survey → Sea trial → Further negotiations or conditions → Completion → Delivery.</em></p><p>The exact process varies according to the yacht, jurisdiction, contracts and transaction structure. The broker's role also varies. But the principle remains: <b>every stage creates information that affects the next decision.</b></p><p><b>Don't rush the client</b></p><p>A client may become emotionally attached very quickly. That is understandable. A yacht is not an ordinary purchase. It may represent freedom, family time, status, adventure, privacy, achievement or a new lifestyle. The broker needs to understand the excitement without becoming carried away by it.</p><p><b>Broker's Insight</b></p><p><b>Your enthusiasm can be useful. Your objectivity is essential.</b></p>", "q": "A client says, \"I like the yacht. Let's go and see it.\" What should the broker do first?", "opts": ["Book the viewing immediately to keep momentum", "Send the client more similar listings", "Tell the client to wait for a survey", "Prepare: confirm why it fits the brief, what is known and unknown, and what the viewing needs to achieve"], "correct": 3}, {"heading": "Exercise: The Pre-Viewing Brief", "body": "<p><b>Try it</b></p><p>Before a client views a yacht, prepare a <b>one-page briefing</b> containing client, yacht, why it fits, questions, potential concerns, practical details and next step.</p>", "exercise": {"intro": "Use a real or fictional yacht. Write it so the client could read it.", "groups": [{"title": "Pre-viewing brief", "section": "yachts", "fields": [{"key": "pv_client", "label": "Client: who is attending?", "type": "short", "min": 10}, {"key": "pv_yacht", "label": "Yacht: what is being viewed?", "type": "short", "min": 10}, {"key": "pv_fit", "label": "Why it fits: which requirements does it appear to meet?", "type": "long", "min": 30}, {"key": "pv_q", "label": "Questions: what needs to be investigated?", "type": "long", "min": 30}, {"key": "pv_conc", "label": "Potential concerns: what should the client pay attention to?", "type": "long", "min": 30}, {"key": "pv_prac", "label": "Practical details: where, when and with whom?", "type": "long", "min": 15}, {"key": "pv_next", "label": "Next step: what decision will the viewing help the client make?", "type": "long", "min": 20}]}]}}, {"heading": "Chapter 2: The Yacht Viewing", "body": "<p><b>A viewing is not a guided tour</b></p><p>A beginner might approach a yacht viewing like this: <em>\"This is the salon. Here is the dining area. This is the master cabin. And here is the beach club.\"</em> A broker thinks differently. The question is not <em>\"What does this yacht have?\"</em> It is: <b>\"How does this yacht work for this client?\"</b></p><p><b>Observe the client</b></p><p>During a viewing, pay attention to what they stop to look at, what they ignore, what they discuss, what they question, what makes them uncomfortable, which spaces they return to, what they compare with previous yachts and what they imagine doing aboard.</p><p>Sometimes the client's body language tells you something their words do not. A client may say <em>\"It's very nice\"</em> but spend three minutes discussing the crew area. That tells you something. Another client may barely comment on the interior but spend twenty minutes on the aft deck. That tells you something too.</p><p><b>Observe the yacht</b></p><p>You are also looking beyond the brochure. Look at general condition, maintenance presentation, cleanliness, layout, flow between spaces, crew areas, storage, access, exterior spaces, tender arrangements, signs of wear, unusual features and things that deserve further investigation. You are not performing a survey. You are developing professional awareness.</p><p><b>Do not pretend to know what you don't know</b></p><p>A client asks: <em>\"Has the engine been rebuilt?\"</em> If you don't know, do not guess. Say: <em>\"I don't want to speculate. I'll verify that and come back to you.\"</em> That answer demonstrates more professionalism than a confident but incorrect answer.</p><p><b>The viewing conversation</b></p><p>A strong broker does not talk continuously. Instead: <b>Observe → Ask → Listen → Clarify → Record.</b> For example: <em>\"How does this layout feel compared with the last yacht we saw?\"</em> Or: <em>\"You mentioned privacy was important. How do you feel about the relationship between the guest areas and crew spaces here?\"</em> The viewing becomes part of the discovery process.</p>", "q": "A client asks, \"Has the engine been rebuilt?\" and you don't know. What do you say?", "opts": ["\"I don't want to speculate. I'll verify that and come back to you.\"", "\"Yes, I believe it was rebuilt recently.\"", "\"Engines on yachts like this rarely need it.\"", "\"That isn't something a buyer should worry about.\""], "correct": 0}, {"heading": "Exercise: The Three-Lens Viewing", "body": "<p><b>Try it</b></p><p>Imagine you are walking through a yacht with a <b>family client.</b> Record what you notice through three lenses: the client (what are they reacting to?), the yacht (what am I observing?) and the questions (what needs verification?). Record at least five observations in each.</p><p>This teaches you to stop seeing a yacht only as a collection of rooms.</p>", "exercise": {"intro": "Five observations per lens, one per line.", "groups": [{"title": "Three-lens viewing notes", "section": "yachts", "fields": [{"key": "tl_client", "label": "CLIENT: what are they reacting to? (at least five)", "type": "long", "min": 60}, {"key": "tl_yacht", "label": "YACHT: what am I observing? (at least five)", "type": "long", "min": 60}, {"key": "tl_q", "label": "QUESTIONS: what needs verification? (at least five)", "type": "long", "min": 60}]}]}}, {"heading": "Chapter 3: The Offer", "body": "<p><b>\"We'll make an offer\" changes everything</b></p><p>A client may view several yachts. Then one day they say: <em>\"I'd like to make an offer.\"</em> The broker's role now becomes particularly important. An offer is not simply a number. Depending on the transaction, it may involve proposed purchase price, deposit, contractual terms, conditions, timing, survey arrangements, sea trial arrangements, inclusions or exclusions, delivery and other negotiated provisions.</p><p>The exact legal structure depends on the transaction and jurisdiction. This is where specialist legal advice becomes essential. The broker should understand the commercial process without pretending to be the lawyer.</p><p><b>Price is only one part of the conversation</b></p><p>Suppose a yacht is asking <b>€8,000,000</b> and the client offers <b>€7,000,000.</b> A beginner may think: <em>\"That's a million below asking.\"</em> A broker asks:</p><p>&bull; How was the asking price established?<br/>&bull; How does it compare with relevant yachts?<br/>&bull; What is the yacht's condition?<br/>&bull; How long has it been on the market?<br/>&bull; Have there been previous offers?<br/>&bull; Is the seller motivated?<br/>&bull; Are there competing buyers?<br/>&bull; What does the client actually want to achieve?<br/>&bull; What terms accompany the price?</p><p>The number has context.</p><p><b>The broker as translator</b></p><p>An offer moves between people with different objectives. The buyer may think: <em>\"This is what I am prepared to pay.\"</em> The seller may hear: <em>\"Your yacht is not worth what you think it is.\"</em> The broker helps turn emotion into professional communication. Instead of <em>\"My client thinks your yacht is overpriced,\"</em> a broker may communicate the commercial reasoning behind the offer clearly and respectfully. Tone matters.</p><p><b>Never negotiate against yourself</b></p><p>If a client gives you a negotiating position, your role is not to casually improve it for the other side. You need to understand what the client wants, what the client is prepared to accept, what authority you actually have, what requires client approval and what should be referred to legal or other professional advisers. Confidentiality and accuracy are critical.</p><p><b>Broker's Insight</b></p><p><b>Never reveal more about your client's position than your client has authorised you to reveal.</b></p>", "q": "What should a broker reveal about the client's negotiating position?", "opts": ["Whatever helps move the deal along fastest", "Everything, to build trust with the seller", "Only what the client has authorised", "Nothing at all, even to the client's lawyer"], "correct": 2}, {"heading": "Exercise: The Offer Conversation", "body": "<p><b>Try it</b></p><p>Your client says: <em>\"We really like the yacht, but we think €8 million is too much. We'd like to start at €7.2 million.\"</em></p><p>Write a short message to the listing broker. It should communicate genuine interest, state the proposed price, avoid insulting the yacht, avoid revealing unnecessary information and create a basis for discussion. Then write three questions you would ask your client before sending the offer.</p>", "exercise": {"intro": "Professional, warm and short. Do not over-explain the client's reasoning.", "groups": [{"title": "Message to the listing broker", "section": "services", "fields": [{"key": "of_msg", "label": "Your message to the listing broker", "type": "long", "min": 80}]}, {"title": "Before I send it", "section": "services", "fields": [{"key": "of_q1", "label": "Question 1 for your client", "type": "short", "min": 15}, {"key": "of_q2", "label": "Question 2 for your client", "type": "short", "min": 15}, {"key": "of_q3", "label": "Question 3 for your client", "type": "short", "min": 15}]}]}}, {"heading": "Chapter 4: Survey & Sea Trial", "body": "<p><b>This is where emotion meets evidence</b></p><p>A yacht may look excellent during a viewing. A professional survey can reveal something completely different. That is not necessarily bad. It is part of the process. The survey exists to help establish the condition and characteristics of the yacht within the agreed scope. A sea trial can provide an opportunity to assess performance and operation under specified conditions. The broker does not become the surveyor. The broker helps coordinate the process and ensures the client understands what is happening.</p><p><b>What might a survey reveal?</b></p><p>Potential findings could include maintenance issues, machinery concerns, corrosion, leaks, wear, electrical issues, structural observations, safety-related items, documentation gaps and items requiring further investigation. Not every finding is a deal-breaker. The important question becomes: <b>what does this finding mean, and what should happen next?</b> That is where specialists become important.</p><p><b>The broker's role</b></p><p>A broker may need to coordinate access, communicate timing, keep parties informed, obtain relevant documentation, relay questions, help organise follow-up, manage expectations and keep the transaction moving. But the broker should not turn into a technical expert overnight. If a technical question arises: <b>find the right expert.</b></p><p><b>The sea trial</b></p><p>A sea trial can allow the parties to observe aspects of the yacht's operation under agreed conditions. Areas of interest might include engines, speed, manoeuvrability, vibration, stabilisation, steering, systems and general operational behaviour. The exact scope should be established with the appropriate professionals. Again: <b>observe, record, verify.</b> Do not diagnose beyond your competence.</p><p><b>When something goes wrong</b></p><p>Imagine the survey identifies a significant issue. The buyer is concerned. The seller is defensive. The transaction becomes tense. A poor broker becomes emotional. A professional broker slows the situation down and asks:</p><p>&bull; What exactly has been identified?<br/>&bull; Is it confirmed?<br/>&bull; How significant is it?<br/>&bull; What does the specialist recommend?<br/>&bull; What are the costs or implications?<br/>&bull; What does the contract say?<br/>&bull; What options are available?<br/>&bull; Who needs to advise the client?</p><p>The answer may be repair, price adjustment, further investigation, revised terms, acceptance, or withdrawal, depending on the contractual framework. The broker facilitates the process. Specialists provide specialist advice.</p>", "q": "A survey reveals a significant issue and the parties become tense. What does a professional broker do?", "opts": ["Play the issue down to save the deal", "Give the client a technical diagnosis", "Push the buyer to walk away immediately", "Slow the situation down, establish exactly what was found and what it means, and involve the right specialists"], "correct": 3}, {"heading": "Chapter 5: Negotiating the Deal", "body": "<p><b>Negotiation is not a battle</b></p><p>Many people imagine negotiation as two people trying to overpower each other. Professional yacht brokerage is usually more subtle. Both sides may want the transaction to happen. The question is: <b>can the parties find terms they can both accept?</b></p><p><b>What is actually being negotiated?</b></p><p>It may not be only price. Negotiation can involve purchase price, timing, conditions, survey findings, delivery, inclusions, exclusions, repairs, documentation, deposit arrangements and other contractual provisions. A €100,000 movement in price may matter less than a condition that changes the practical risk of ownership.</p><p><b>Know your client's priorities</b></p><p>Before negotiating, understand:</p><p>&bull; <b>Must have:</b> what cannot be compromised?<br/>&bull; <b>Strong preference:</b> what matters significantly?<br/>&bull; <b>Flexible:</b> what can move?<br/>&bull; <b>Unknown:</b> what has the client not yet considered?</p><p>Without this understanding, the broker can negotiate blindly.</p><p><b>Don't negotiate from emotion</b></p><p>Imagine the seller says: <em>\"We will not accept anything below €7.7m.\"</em> The client says: <em>\"That's ridiculous. Tell them we'll walk.\"</em> The broker should not immediately transmit the emotion. Instead: <em>\"I understand. Before I respond, let me make sure I understand your position. Is €7.7m your absolute ceiling, or is there another term that could make the overall deal more attractive?\"</em> The objective is clarity.</p><p><b>Silence is part of negotiation</b></p><p>A broker does not need to fill every pause. After communicating a position, give the other side room to respond. Listen carefully. Sometimes the most valuable information appears after the first answer.</p><p><b>Never invent urgency</b></p><p>Do not tell a client <em>\"There are three other buyers ready to purchase tomorrow\"</em> unless you actually know that to be true. Do not tell a seller <em>\"My client is your only serious buyer\"</em> unless that is established and authorised. False urgency can damage trust and transactions.</p><p><b>Broker's Insight</b></p><p><b>Your reputation is worth more than winning one negotiation.</b></p>", "q": "What should a broker do before negotiating for a client?", "opts": ["Open with the lowest possible number", "Understand the client's must-haves, strong preferences and flexible points", "Wait for the seller to reveal their position", "Create urgency to pressure the other side"], "correct": 1}, {"heading": "Exercise: The Negotiation Map", "body": "<p><b>Try it</b></p><p>Create a negotiation map for this fictional transaction:</p><p>&bull; <b>Asking price:</b> €8.0m<br/>&bull; <b>Buyer opening position:</b> €7.2m<br/>&bull; <b>Buyer ideal outcome:</b> €7.5m<br/>&bull; <b>Seller target:</b> €7.8m</p><p>List five buyer's priorities, five seller's priorities, five areas that might be flexible and five pieces of information you still need. Then answer: <b>what could create value without simply moving the price?</b></p>", "exercise": {"intro": "Five of each. Think beyond price.", "groups": [{"title": "Negotiation map", "section": "sales", "fields": [{"key": "nm_buyer", "label": "Buyer's priorities (five)", "type": "long", "min": 50}, {"key": "nm_seller", "label": "Seller's priorities (five)", "type": "long", "min": 50}, {"key": "nm_flex", "label": "Areas that might be flexible (five)", "type": "long", "min": 50}, {"key": "nm_info", "label": "Information you still need (five)", "type": "long", "min": 50}]}, {"title": "Creating value", "section": "sales", "fields": [{"key": "nm_value", "label": "What could create value without simply moving the price?", "type": "long", "min": 50}]}]}}, {"heading": "Chapter 6: Closing & Delivery", "body": "<p><b>The deal is not finished when everyone says \"yes\"</b></p><p>A verbal agreement is not the end. There may still be contractual conditions, documentation, deposits, survey matters, financing, registration, insurance, final inspections, completion arrangements, delivery logistics and ownership transfer requirements. The exact requirements depend on the transaction. This is why experienced brokers respect the closing process.</p><p><b>The final stretch</b></p><p>This can be one of the most stressful periods. Everyone is tired. The buyer wants the yacht. The seller wants completion. Lawyers are reviewing documents. Specialists may still be resolving issues. Small misunderstandings can become major problems. The broker's job is to maintain communication and momentum while staying within their role.</p><p><b>Delivery</b></p><p>Delivery is more than handing someone the keys. The parties need to establish when and where delivery occurs, what is included, what documentation is provided, what condition the yacht is in, what obligations remain, what happens to crew and operational arrangements and any other agreed requirements. The details depend on the contract and transaction.</p><p><b>The emotional moment</b></p><p>After months of work, the transaction completes. The client finally owns the yacht. For a new owner, this can be a major personal milestone. For the broker, however, the relationship may be just beginning. A completed transaction can lead to future purchases, future sales, referrals, management relationships, charter opportunities and introductions to other clients.</p><p>The best brokers do not disappear after the commission is earned. They continue to be useful.</p>", "q": "Buyer and seller have verbally agreed. Is the transaction finished?", "opts": ["Yes, the broker's work is now done", "Yes, only the paperwork remains and it is a formality", "No. The contractual process, conditions, documentation, completion and delivery still need to be completed", "No, but only the deposit remains outstanding"], "correct": 2}, {"heading": "Professional Output: My Yacht Transaction Map", "body": "<p><b>The complete transaction map</b></p><p>Take everything you have learned and create your own transaction map from <b>client to closing to delivery.</b> For every stage write the client's objective, the broker's role, what could go wrong and who else may need to be involved.</p><p>Then add a final section, <b>Where I Add Value.</b> Write five sentences beginning: <em>\"A broker adds value by...\"</em></p><p>This becomes a core page in your Broker Portfolio.</p>", "exercise": {"intro": "For each stage: client objective, broker role, potential risk, other professionals involved.", "groups": [{"title": "My transaction map", "section": "sales", "fields": [{"key": "tm_01", "label": "1. Client", "type": "long", "min": 40, "placeholder": "Client objective / broker role / what could go wrong / who else is involved"}, {"key": "tm_02", "label": "2. Qualification", "type": "long", "min": 40, "placeholder": "Client objective / broker role / what could go wrong / who else is involved"}, {"key": "tm_03", "label": "3. Search", "type": "long", "min": 40, "placeholder": "Client objective / broker role / what could go wrong / who else is involved"}, {"key": "tm_04", "label": "4. Shortlist", "type": "long", "min": 40, "placeholder": "Client objective / broker role / what could go wrong / who else is involved"}, {"key": "tm_05", "label": "5. Viewing", "type": "long", "min": 40, "placeholder": "Client objective / broker role / what could go wrong / who else is involved"}, {"key": "tm_06", "label": "6. Further investigation", "type": "long", "min": 40, "placeholder": "Client objective / broker role / what could go wrong / who else is involved"}, {"key": "tm_07", "label": "7. Offer", "type": "long", "min": 40, "placeholder": "Client objective / broker role / what could go wrong / who else is involved"}, {"key": "tm_08", "label": "8. Negotiation", "type": "long", "min": 40, "placeholder": "Client objective / broker role / what could go wrong / who else is involved"}, {"key": "tm_09", "label": "9. Agreement", "type": "long", "min": 40, "placeholder": "Client objective / broker role / what could go wrong / who else is involved"}, {"key": "tm_10", "label": "10. Survey", "type": "long", "min": 40, "placeholder": "Client objective / broker role / what could go wrong / who else is involved"}, {"key": "tm_11", "label": "11. Sea trial", "type": "long", "min": 40, "placeholder": "Client objective / broker role / what could go wrong / who else is involved"}, {"key": "tm_12", "label": "12. Further negotiation / conditions", "type": "long", "min": 40, "placeholder": "Client objective / broker role / what could go wrong / who else is involved"}, {"key": "tm_13", "label": "13. Closing", "type": "long", "min": 40, "placeholder": "Client objective / broker role / what could go wrong / who else is involved"}, {"key": "tm_14", "label": "14. Delivery", "type": "long", "min": 40, "placeholder": "Client objective / broker role / what could go wrong / who else is involved"}, {"key": "tm_15", "label": "15. Relationship continues", "type": "long", "min": 40, "placeholder": "Client objective / broker role / what could go wrong / who else is involved"}]}, {"title": "Where I add value", "section": "services", "fields": [{"key": "av_1", "label": "A broker adds value by... (1)", "type": "long", "min": 20}, {"key": "av_2", "label": "A broker adds value by... (2)", "type": "long", "min": 20}, {"key": "av_3", "label": "A broker adds value by... (3)", "type": "long", "min": 20}, {"key": "av_4", "label": "A broker adds value by... (4)", "type": "long", "min": 20}, {"key": "av_5", "label": "A broker adds value by... (5)", "type": "long", "min": 20}]}]}}, {"heading": "Broker's Notebook: What Changed", "body": "<p><b>Broker's notebook</b></p><p>Write down the three ideas from this module that changed your understanding of yacht brokerage. Then complete this sentence: <em>\"I previously thought selling a yacht was mainly about ________. I now understand that it also involves ________.\"</em></p>", "exercise": {"intro": "Three ideas, then the sentence.", "groups": [{"title": "What changed", "section": "profile", "fields": [{"key": "nb6_1", "label": "Idea 1", "type": "long", "min": 20}, {"key": "nb6_2", "label": "Idea 2", "type": "long", "min": 20}, {"key": "nb6_3", "label": "Idea 3", "type": "long", "min": 20}, {"key": "nb6_sentence", "label": "\"I previously thought selling a yacht was mainly about ___. I now understand that it also involves ___.\"", "type": "long", "min": 30}]}]}}, {"heading": "Broker Challenge: The Deal Under Pressure", "body": "<p><b>The deal under pressure</b></p><p>You are representing a buyer. The client has found a yacht they love. The initial offer has been accepted subject to the agreed contractual process. The survey then identifies several issues. One is relatively minor. One requires further technical investigation. One could potentially involve a significant future expense. The client calls you and says:</p><p><em>\"I still love the yacht, but I'm nervous. What would you do?\"</em></p><p>Do <b>not</b> immediately tell the client whether to proceed. Prepare your response using the seven steps below. The objective is not to demonstrate technical expertise. It is to demonstrate <b>professional judgment.</b></p>", "exercise": {"intro": "Structure matters more than the verdict.", "groups": [{"title": "My response to the client", "section": "sales", "fields": [{"key": "dp_ack", "label": "1. Acknowledge: how would you respond to the client's concern?", "type": "long", "min": 30}, {"key": "dp_clar", "label": "2. Clarify: what do you need to know about the findings?", "type": "long", "min": 30}, {"key": "dp_ver", "label": "3. Verify: which specialists should be involved?", "type": "long", "min": 30}, {"key": "dp_und", "label": "4. Understand: what are the financial, operational or practical implications?", "type": "long", "min": 30}, {"key": "dp_rev", "label": "5. Review: what does the transaction documentation say about the issue?", "type": "long", "min": 30}, {"key": "dp_opt", "label": "6. Present options: what possible paths could exist?", "type": "long", "min": 30}, {"key": "dp_ret", "label": "7. Return the decision to the client: how would you help them decide without deciding for them?", "type": "long", "min": 30}]}]}}, {"heading": "Reflection: Where I Stand", "body": "<p><b>Reflection</b></p><p>You have now followed a yacht transaction from interest to completion. These questions matter. Because brokerage is not only about selling. It is about helping people make important decisions while the situation keeps changing.</p>", "exercise": {"intro": "Answer honestly.", "groups": [{"title": "My signals", "section": "profile", "fields": [{"key": "rf6_stage", "label": "Which stage interests me most?", "type": "short", "min": 10}, {"key": "rf6_uncomf", "label": "Which stage makes me most uncomfortable?", "type": "short", "min": 10}, {"key": "rf6_pp", "label": "Do I enjoy the combination of people and process?", "type": "short", "min": 10}, {"key": "rf6_uncert", "label": "How comfortable am I with uncertainty?", "type": "short", "min": 10}, {"key": "rf6_calm", "label": "Could I stay calm when a transaction becomes difficult?", "type": "short", "min": 10}, {"key": "rf6_facts", "label": "Do I naturally look for facts before forming an opinion?", "type": "short", "min": 10}, {"key": "rf6_comm", "label": "Can I communicate difficult information without creating unnecessary conflict?", "type": "short", "min": 10}]}]}}, {"heading": "Final Reflection and What Comes Next", "body": "<p><b>Module 6: final reflection</b></p><p>You now understand something important. A yacht sale is not one event. It is a chain of decisions. At every stage, the broker is helping transform uncertainty into clarity.</p><p>The best broker does not pretend that problems do not exist. They help the client understand the problem. They find the right people. They keep communication moving. They protect trust. And they help the transaction reach the right outcome for the client.</p><p>You have now learned the basic architecture of the deal. The next question is more personal: <b>can you actually think like the person doing this work?</b> That is where the academy changes direction.</p><p><b>What comes next</b></p><p><b>Module 7: Think Like a Broker.</b> <em>Can I actually do this?</em> You have learned about yachts, the market, clients, the brokerage and the transaction. Now it is time to stop being the student observing the broker. You become the broker.</p><p>You will receive information. You will have incomplete information. You will have competing options. You will need to ask better questions, decide what matters and make recommendations. And sometimes, you will need to say: <em>\"I don't think this is the right yacht.\"</em> That is when brokerage becomes judgment.</p>", "q": "What is a yacht sale, as this module describes it?", "opts": ["A chain of decisions in which the broker helps turn uncertainty into clarity", "A single event that happens at signing", "A contest between buyer and seller", "A purely legal process the broker watches"], "correct": 0}]$json$;
  v_final jsonb := $json$[{"q": "Why does the transaction begin before the viewing?", "opts": ["Because the broker must first agree the price", "Because viewings are optional in yacht sales", "Because the broker needs to understand the client, prepare the opportunity, identify what is known and unknown, and establish what the viewing needs to accomplish", "Because the seller must approve the client first"], "correct": 2}, {"q": "What should a broker do when they don't know the answer to a technical question?", "opts": ["Say they need to verify it and involve the appropriate specialist rather than speculate", "Give their best estimate to keep the client confident", "Change the subject until the viewing ends", "Tell the client the question is not important"], "correct": 0}, {"q": "Is an offer only about price?", "opts": ["Yes, price is the only negotiable element", "Yes, everything else is decided by lawyers alone", "No, price is never part of an offer", "No. Depending on the transaction, terms, conditions, timing, survey arrangements, delivery and other contractual matters may also be important"], "correct": 3}, {"q": "What is the purpose of a survey?", "opts": ["To set the final asking price", "To help establish the yacht's condition and identify matters requiring attention, within the agreed scope and with appropriate professional expertise", "To let the broker inspect the yacht", "To confirm the seller's identity"], "correct": 1}, {"q": "Should a broker perform the survey?", "opts": ["Yes, brokers know the yacht best", "No. A broker coordinates and communicates within their role; qualified specialists provide technical inspection and advice", "Yes, to reduce the cost to the client", "Only if the yacht is under 30 metres"], "correct": 1}, {"q": "Why should a broker understand a client's priorities before negotiating?", "opts": ["So they can negotiate without asking the client again", "So they can share the priorities with the seller", "So the price can be settled immediately", "So they know what is essential, what is flexible and what requires client approval"], "correct": 3}, {"q": "Is the transaction finished when buyer and seller verbally agree?", "opts": ["Yes, a verbal agreement is binding in every case", "Yes, the broker's work ends there", "No. The agreed contractual process, conditions, documentation, completion and delivery still need to be completed", "No, only the deposit needs to be paid"], "correct": 2}]$json$;
begin
  select id into v_module from public.academy_modules where track = 'yachts' and module_number = 6;
  if v_module is null then
    raise exception 'Yachts module 6 not found';
  end if;

  update public.academy_modules
     set title = 'The Art of the Deal', description = 'How does a yacht actually get sold?'
   where id = v_module;

  delete from public.academy_module_pages where module_id = v_module;
  delete from public.academy_quiz_questions where module_id = v_module;

  for rec in select * from jsonb_array_elements(v_pages) loop
    n := n + 1;
    if rec ? 'exercise' then
      insert into public.academy_module_pages (module_id, page_number, heading, body_html, checkpoint_question_id, exercise)
      values (v_module, n, rec->>'heading', rec->>'body', null, rec->'exercise');
    else
      insert into public.academy_quiz_questions (module_id, question_text, order_index, stage, page_number)
      values (v_module, rec->>'q', 0, 'checkpoint', n)
      returning id into v_q;

      for i in 0 .. jsonb_array_length(rec->'opts') - 1 loop
        insert into public.academy_quiz_options (question_id, option_text, is_correct, order_index)
        values (v_q, rec->'opts'->>i, i = (rec->>'correct')::int, i);
      end loop;

      insert into public.academy_module_pages (module_id, page_number, heading, body_html, checkpoint_question_id)
      values (v_module, n, rec->>'heading', rec->>'body', v_q);
    end if;
  end loop;

  n := 0;
  for rec in select * from jsonb_array_elements(v_final) loop
    n := n + 1;
    insert into public.academy_quiz_questions (module_id, question_text, order_index, stage)
    values (v_module, rec->>'q', n - 1, 'final')
    returning id into v_q;

    for i in 0 .. jsonb_array_length(rec->'opts') - 1 loop
      insert into public.academy_quiz_options (question_id, option_text, is_correct, order_index)
      values (v_q, rec->'opts'->>i, i = (rec->>'correct')::int, i);
    end loop;
  end loop;
end
$mig$;
